// Writes supabase/setup.sql: the table definitions plus the sample events,
// so the whole database can be set up with one paste into the SQL Editor.
// Usage: npx tsx scripts/generate-setup-sql.ts
import { readFileSync, writeFileSync } from 'node:fs';

import { SAMPLE_EVENTS } from '../src/data/sampleEvents';

const q = (s: string) => `'${s.replaceAll("'", "''")}'`;
const lines = [
  '-- Generated by scripts/generate-setup-sql.ts. Edit supabase/schema.sql or src/data/sampleEvents.ts instead.',
  '',
  readFileSync('supabase/schema.sql', 'utf8'),
  '-- Sample events',
];
SAMPLE_EVENTS.forEach((e, i) => {
  lines.push(
    `insert into events (id, club_id, name, track, location, sort) values (${q(e.id)}, ${q(e.clubId)}, ${q(e.name)}, ${q(e.track)}, ${q(e.location)}, ${i})`,
    '  on conflict (id) do nothing;',
  );
  for (const d of e.days) {
    lines.push(
      `insert into event_days (id, event_id, label, date, items) values (${q(d.id)}, ${q(e.id)}, ${q(d.label)}, ${q(d.date)}, ${q(JSON.stringify(d.items))}::jsonb)`,
      '  on conflict (id) do nothing;',
    );
  }
});
writeFileSync('supabase/setup.sql', lines.join('\n') + '\n');
